#include <stdio.h>

enum TrayState { RECEIVED = 1, CHECKED = 2, STORED = 3 };

struct Tray {
    int id;
    enum TrayState state;
};

static int move_tray(struct Tray *tray, enum TrayState next)
{
    if (!((tray->state == RECEIVED && next == CHECKED) ||
          (tray->state == CHECKED && next == STORED))) {
        return 0;
    }
    tray->state = next;
    return 1;
}

int main(void)
{
    struct Tray tray = {41, RECEIVED};
    puts(move_tray(&tray, STORED) ? "ok" : "denied");
    printf("%d:%d\n", tray.id, (int)tray.state);
    puts(move_tray(&tray, CHECKED) ? "ok" : "denied");
    printf("%d:%d\n", tray.id, (int)tray.state);
    return 0;
}

