#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_values(int values[], const int minimum[], const int maximum[], size_t count)
{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < minimum[i] || value > maximum[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) {
            return 0;
        }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) {
        ++cursor;
    }
    return *cursor == '\0';
}

enum State { NEW = 1, ACTIVE = 2, DONE = 3 };

struct Request {
    int id;
    enum State state;
};

static struct Request *lookup(struct Request requests[], size_t count, int id)
{
    for (size_t i = 0; i < count; ++i) {
        if (requests[i].id == id) {
            return &requests[i];
        }
    }
    return NULL;
}

static const char *apply(struct Request requests[], size_t *count, size_t capacity,
                         int operation, int id, int state)
{
    if (state != NEW && state != ACTIVE && state != DONE) {
        return "invalid";
    }
    struct Request *request = lookup(requests, *count, id);
    if (operation == 1) {
        if (state != NEW) {
            return "invalid";
        }
        /* TODO: reject an existing identifier before making a change. */
        if (*count == capacity) {
            return "full";
        }
        requests[*count] = (struct Request){ .id = id, .state = NEW };
        ++*count;
        return "ok";
    }
    if (request == NULL) {
        return "missing";
    }
    if ((request->state == NEW && state == ACTIVE) ||
        (request->state == ACTIVE && state == DONE)) {
        request->state = (enum State)state;
        return "ok";
    }
    return "denied";
}

int main(void)
{
    int value[6];
    const int minimum[] = {1, 1, 0, 1, 1, 0};
    const int maximum[] = {2, 9999, 9, 2, 9999, 9};
    if (!read_values(value, minimum, maximum, 6)) {
        puts("invalid");
        return 0;
    }
    struct Request requests[3] = {{101, NEW}, {203, ACTIVE}};
    size_t count = 2;
    const size_t capacity = sizeof requests / sizeof requests[0];
    puts(apply(requests, &count, capacity, value[0], value[1], value[2]));
    puts(apply(requests, &count, capacity, value[3], value[4], value[5]));
    for (size_t i = 0; i < count; ++i) {
        printf("%s%d:%d", i == 0 ? "" : " ", requests[i].id, (int)requests[i].state);
    }
    putchar('\n');
    return 0;
}

